// Safety checks before anything is sent. Any failure stops the whole batch with an error,
// and because this runs before 'Respond to Webhook', MailMate shows that error.
const TEST_TO = 'REPLACE_WITH_YOUR_TEST_ADDRESS';  // your secondary inbox (MAILMATE_TEST_ADDRESS in .env)
const REAL_SENDING_ENABLED = true;                 // Step 7: real batches allowed (MailMate checks cap, window, approval)
const MAX_BATCH = 20;                              // daily cap

if (TEST_TO.startsWith('REPLACE')) throw new Error('Set TEST_TO at the top of the Explode + guard node first');
const wh = $('Webhook').first();
let payload;
try { payload = JSON.parse(wh.json.body.payload); } catch (err) { throw new Error('payload is not valid JSON'); }
const testMode = payload.test_mode === true;
const emails = payload.emails;
if (!Array.isArray(emails) || emails.length === 0) throw new Error('No emails in the batch');
if (emails.length > MAX_BATCH) throw new Error(`Batch of ${emails.length} is larger than ${MAX_BATCH} - refused`);
if (!testMode && !REAL_SENDING_ENABLED) throw new Error('Real sending is not enabled in W2 yet (test mode only)');

// The resume: whatever name n8n gave the uploaded file, pass it on as `resume`.
const files = wh.binary || {};
const key = Object.keys(files)[0];
if (!key) throw new Error('No resume file received');
const resume = files[key];
if (resume.mimeType && resume.mimeType !== 'application/pdf') throw new Error(`Resume must be a PDF, got ${resume.mimeType}`);

// Spacing between sends, with a floor so a bad payload can't send in a burst.
const min = Math.max(Number(payload.spacing_min_s) || 180, testMode ? 30 : 120);
const max = Math.max(Number(payload.spacing_max_s) || 420, min);

return emails.map(e => {
  const to = String(e.to || '').trim().toLowerCase();
  if (testMode && to !== TEST_TO.toLowerCase()) throw new Error(`Test mode may only send to the test address, got ${to}`);
  if (!to || !e.subject || !e.body_text || !e.body_html) throw new Error(`Email ${e.email_id} is missing to, subject, body_text or body_html`);
  if (e.reply_to_message_id) throw new Error('Follow-ups are not supported yet (Step 9)');
  return {
    json: {
      email_id: e.email_id, to, subject: e.subject, body_text: e.body_text, body_html: e.body_html,
      test_mode: testMode, batch_id: payload.batch_id, sender_name: payload.sender_name || '',
      spacing_min_s: min, spacing_max_s: max,
    },
    binary: { resume },
  };
});
